const obs=new IntersectionObserver(e=>{e.forEach(n=>{if(n.isIntersecting){n.target.classList.add('v');obs.unobserve(n.target)}})},{threshold:.1});document.querySelectorAll('.fi').forEach(el=>obs.observe(el));
