// Particles
const S=['#FF6B2B','#FF2255','#CC00AA','#8844FF','#4488FF','#00D4FF'],cv=document.getElementById('c'),cx=cv.getContext('2d');
let W,H;function rs(){W=cv.width=innerWidth;H=cv.height=innerHeight}rs();addEventListener('resize',rs);
const P=[];for(let i=0;i<40;i++)P.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.15,vy:(Math.random()-.5)*.15,r:Math.random()*1.5+.5,c:S[~~(Math.random()*6)],a:Math.random()*.06+.02});
function draw(){cx.clearRect(0,0,W,H);P.forEach(p=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0)p.x=W;if(p.x>W)p.x=0;if(p.y<0)p.y=H;if(p.y>H)p.y=0;cx.beginPath();cx.arc(p.x,p.y,p.r,0,6.28);cx.fillStyle=p.c;cx.globalAlpha=p.a;cx.fill()});
P.forEach((a,i)=>{for(let j=i+1;j<P.length;j++){const b=P[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.sqrt(dx*dx+dy*dy);if(d<100){cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(b.x,b.y);cx.strokeStyle=a.c;cx.globalAlpha=.02*(1-d/100);cx.lineWidth=.5;cx.stroke()}}});
cx.globalAlpha=1;requestAnimationFrame(draw)}draw();

// Metric counters
let ct=false;
const mo=new IntersectionObserver(e=>{e.forEach(n=>{if(n.isIntersecting&&!ct){ct=true;document.querySelectorAll('.metric-val[data-t]').forEach(el=>{const t=+el.dataset.t;let c=0;const s=Math.max(1,t/50),id=setInterval(()=>{c+=s;if(c>=t){el.textContent=t;clearInterval(id)}else el.textContent=~~c},30)})}})},{threshold:.3});
document.querySelector('.metrics')&&mo.observe(document.querySelector('.metrics'));

// Fade-in
const obs=new IntersectionObserver(e=>{e.forEach(n=>{if(n.isIntersecting){n.target.classList.add('v');obs.unobserve(n.target)}})},{threshold:.1});
document.querySelectorAll('.fi').forEach(el=>obs.observe(el));

